// --- Скриншот боковой панели (_side_screens.php) ---
// Структура таблицы повторяет оригинальный _side_screens.php (см. приложенный
// HTML): отдельная таблица с отступом 15px над скриншотом и 20px под ним,
// чтобы между блоком _hot.php (news/banner/contest) и скриншотом был
// нормальный зазор. Ссылка открывает скриншот в попапе через screen_view(),
// если эта функция определена на странице (как в оригинале); иначе — обычный href.
function showRandomSidebarScreen() {
  if (!window.sidebarScreens || sidebarScreens.length === 0) return;
  var s = sidebarScreens[Math.floor(Math.random() * sidebarScreens.length)];
  var c = document.getElementById('sidebar_screen');
  if (!c) return;

  var href;
  if (typeof window.screen_view === 'function') {
    href = "javascript:screen_view('" + s.view + "')";
  } else {
    href = s.view;
  }

  var html = '<table cellpadding="0" cellspacing="0" border="0">';
  html += '<tr><td><img src="images/_dot.gif" width="1" height="15" border="0"></td></tr>';
  html += '<tr><td><a href="' + href + '"><img src="' + s.img + '" border="0"></a></td></tr>';
  html += '<tr><td><img src="images/_dot.gif" width="1" height="20" border="0"></td></tr>';
  html += '<tr><td></td></tr>';
  html += '</table>';
  c.innerHTML = html;
}

// --- Определение текущей страницы из URL ---
// NOTE: segments are matched with [^_.]+ (NOT \w+) — \w includes the
// underscore, so /\w+/ would greedily swallow the rest of the filename
// (e.g. _t_(\w+) -> "community_s_contest_ss_rating_id_35_c_index_13") and
// every isContest/isChronoPage/isDownloadsMobile check would fail, so the
// contest block would never render. [^_.]+ stops at the next _ or the .html.
function getPageInfo() {
  var path = window.location.pathname;
  var page = {};
  var m = path.match(/_t_([^_.]+)/);
  page.t = m ? m[1] : '';
  m = path.match(/_s_([^_.]+)/);
  page.s = m ? m[1] : '';
  m = path.match(/_ss_([^_.]+)/);
  page.ss = m ? m[1] : '';
  return page;
}

// --- Боковая панель _hot.php: полная репликация PHP логики ---
// Правила (из _hot.php):
// 1. gameplay & chronology: chronology ИСКЛЮЧЕНА → всегда news+banner
// 2. community & contest & story: chronology ИСКЛЮЧЕНА → всегда contest блок
// 3. community & contest & (rating|conditions|monsters):
//    ch==1 (25%) → chronology; else (75%) → contest блок
// 4. downloads & mobile: всегда flash ($i принудительно 1)
// 5. Остальные: ch==1 (25%) → chronology; else (75%) → news+banner
//
// Возвращает тип показанного блока: 'chronology' | 'contest' | 'newsBanner' | null.
// 'chronology' используется вызывающим кодом, чтобы скрыть блок скриншота sidebarScreens.
function showRandomSidebarBlock() {
  var container = document.getElementById('sidebar_hot_block');
  if (!container) return null;

  var info = getPageInfo();
  var isChronoPage = (info.t === 'game' && info.s === 'gameplay' && info.ss === 'chronology');
  var isContestStory = (info.t === 'community' && info.s === 'contest' && info.ss === 'story');
  var isContest = (info.t === 'community' && info.s === 'contest');
  var isCommunity = (info.t === 'community');
  var isDownloadsMobile = (info.t === 'downloads' && info.s === 'mobile');

  if (isContestStory) {
    showContestBlock(container);
    return 'contest';
  }

  var chCanShowChrono = !isChronoPage;
  var ch = Math.floor(Math.random() * 4) + 1;

  if (ch === 1 && chCanShowChrono && window.sidebarChrono && sidebarChrono.length > 0) {
    showChronologyBlock(container);
    return 'chronology';
  }

  if (isContest) {
    showContestBlock(container);
    return 'contest';
  }
  
    if (isCommunity) {
    showContestBlock(container);
    return 'contest';
  }

  var i;
  if (isDownloadsMobile) {
    i = 1;
  } else {
    i = Math.floor(Math.random() * 2) + 1;
  }
  showNewsBannerBlock(container, i);
  return 'newsBanner';
}

